import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_CPP_SRC = r"""
#include <torch/extension.h>
torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);
"""

_CUDA_SRC = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

__global__ void layernorm_fwd_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ y,
    const int64_t rows,
    const int64_t n,
    const float eps) {
  const int64_t row = blockIdx.x;
  if (row >= rows) return;
  const int64_t base = row * n;
  __shared__ float s_sum[256];
  __shared__ float s_sq[256];
  float local_sum = 0.0f;
  float local_sq = 0.0f;
  if ((n & 3) == 0) {
    const int64_t n4 = n >> 2;
    const float4* x4 = reinterpret_cast<const float4*>(x + base);
    for (int64_t i = threadIdx.x; i < n4; i += blockDim.x) {
      const float4 v = x4[i];
      local_sum += v.x + v.y + v.z + v.w;
      local_sq += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
    }
  } else {
    for (int64_t i = threadIdx.x; i < n; i += blockDim.x) {
      const float v = x[base + i];
      local_sum += v;
      local_sq += v * v;
    }
  }
  s_sum[threadIdx.x] = local_sum;
  s_sq[threadIdx.x] = local_sq;
  __syncthreads();
  for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
    if (threadIdx.x < s) {
      s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
      s_sq[threadIdx.x] += s_sq[threadIdx.x + s];
    }
    __syncthreads();
  }
  const float mean = s_sum[0] / static_cast<float>(n);
  float var = s_sq[0] / static_cast<float>(n) - mean * mean;
  var = fmaxf(var, 0.0f);
  const float rstd = rsqrtf(var + eps);
  if ((n & 3) == 0) {
    const int64_t n4 = n >> 2;
    const float4* x4 = reinterpret_cast<const float4*>(x + base);
    const float4* w4 = reinterpret_cast<const float4*>(weight);
    const float4* b4 = reinterpret_cast<const float4*>(bias);
    float4* y4 = reinterpret_cast<float4*>(y + base);
    for (int64_t i = threadIdx.x; i < n4; i += blockDim.x) {
      const float4 xv = x4[i];
      const float4 wv = w4[i];
      const float4 bv = b4[i];
      float4 out;
      out.x = (xv.x - mean) * rstd * wv.x + bv.x;
      out.y = (xv.y - mean) * rstd * wv.y + bv.y;
      out.z = (xv.z - mean) * rstd * wv.z + bv.z;
      out.w = (xv.w - mean) * rstd * wv.w + bv.w;
      y4[i] = out;
    }
  } else {
    for (int64_t i = threadIdx.x; i < n; i += blockDim.x) {
      y[base + i] = (x[base + i] - mean) * rstd * weight[i] + bias[i];
    }
  }
}

torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "weight/bias must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat && bias.scalar_type() == at::kFloat,
              "weight/bias must be float32");
  TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
  TORCH_CHECK(weight.is_contiguous() && bias.is_contiguous(), "weight/bias must be contiguous");

  const int64_t n = weight.numel();
  TORCH_CHECK(bias.numel() == n, "bias must have the same number of elements as weight");
  TORCH_CHECK(x.numel() % n == 0, "last dimensions of x must match normalized_shape");
  const int64_t rows = x.numel() / n;

  auto y = at::empty_like(x);
  if (rows == 0 || n == 0) return y;

  const int threads = 256;
  const dim3 blocks(static_cast<unsigned int>(rows));
  auto stream = at::cuda::getCurrentCUDAStream();
  layernorm_fwd_kernel<<<blocks, threads, 0, stream>>>(
      x.data_ptr<float>(),
      weight.data_ptr<float>(),
      bias.data_ptr<float>(),
      y.data_ptr<float>(),
      rows,
      n,
      static_cast<float>(eps));
  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return y;
}
"""

_ext = load_inline(
    name="custom_layernorm_ext",
    cpp_sources=[_CPP_SRC],
    cuda_sources=[_CUDA_SRC],
    functions=["layernorm_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    LayerNorm implemented with a single custom CUDA kernel.
    """

    def __init__(self, normalized_shape: tuple):
        super().__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(self.normalized_shape, dtype=torch.float32))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape, dtype=torch.float32))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            x = x.cuda()
        x = x.contiguous().float()
        weight = self.weight.to(device=x.device, dtype=torch.float32).contiguous()
        bias = self.bias.to(device=x.device, dtype=torch.float32).contiguous()
        return _ext.layernorm_forward(x, weight, bias, self.eps)

